/**
 * Administrator metadata lookup requests behind /imports/:id/lookup: reading the allowlisted lookup view with the import's
 * summary state, submitting a name, retrying, choosing a candidate (or none) and answering conflicts. Each change runs inside
 * mutateAdminImport, so it is one
 * receipt (`lookup`, `lookup-retry`, `lookup-choose` or `lookup-resolve`) and one transaction with the lookup record: a refusal
 * writes nothing, and a lost response replays. Bodies are bounded and shaped before their intent is fingerprinted; the body parsers
 * and the record write are shared with an existing-Album review's requests (catalogReviewLookupRequests.ts).
 */
import { ObjectId, type ClientSession } from 'mongodb';
import { ADMIN_IMPORT_LIMITS, AdminImportError, exact, invalidImport, objectId, record } from '../import/adminImportContract';
import { DRAFT_V2_LIMITS, hasOwn, type ImportDecisionV2 } from '../import/adminImportDraft';
import {
    dailyAnalysisAttemptsUsed, importCollection, importLookupRecord, importPurposeFilter, importSavedIdentity, mutateAdminImport, parseAdminProjectMutation, withImportAdmin
} from '../import/adminImportService';
import { importIdentityPreselections } from '../import/adminImportIdentity';
import { importIdentityAnswers, importSummaryView, type ImportAppendTarget, type ImportSummaryView } from '../import/adminImportSummary';
import { metadataLookupConfiguration, type MetadataLookupConfiguration } from '../../config/metadataLookup';
import { boundedJson, parseDraftPath } from '../import/adminImportValueState';
import { isLookupCandidateKey, METADATA_LOOKUP_LIMITS } from './lookupContract';
import { importLookupView, type ImportLookupView } from './lookupView';
import { REVIEW_LOOKUP_LIMITS } from './lookupReviewValues';
import { chooseLookupCandidate, isLookupValuePath, resolveLookupConflicts } from './lookupValueApplication';
import { adminImportLookupCollection, metadataLookupAdmitted, queueMetadataLookup, readLookupApplicationContext } from './metadataLookupService';
import { importMusicBrainzNameMap } from '../import/adminImportMusicBrainzIds';
import type { MetadataLookupRecord, MetadataLookupSubmission } from './metadataLookupRecord';
import { getDb } from '../../infrastructure/database';
import { readyAlbumLifecycleFilter } from '../../services/catalog/albumReferenceFenceService';
import { hasStoredExpectedTracklist } from '../../services/catalog/albumExpectedTracklist';

/** One answer per draft value: the five album paths and three per file (a review: REVIEW_LOOKUP_LIMITS.answers). */
const maximumAnswers = 5 + 3 * 100;
const notFound = () => new AdminImportError(404, 'ADMIN_IMPORT_NOT_FOUND');
/** A run number and a candidate key (a MusicBrainz or iTunes-only candidate's, or null for none), both present as own properties. */
function boundRunAndCandidate(body: Record<string, unknown>) {
    if (!hasOwn(body, 'run') || !hasOwn(body, 'candidateKey') || !Number.isSafeInteger(body.run) || (body.run as number) < 1
        || (body.candidateKey !== null && !isLookupCandidateKey(body.candidateKey))) invalidImport();
    return { run: body.run as number, candidateKey: body.candidateKey as string | null };
}
/** Stores a record replaced by a choice or an answer for the run it was read with; any other match is a conflict. */
export async function storeLookupRecord(next: MetadataLookupRecord, session: ClientSession) {
    const written = await adminImportLookupCollection().replaceOne({ _id: next._id, run: next.run }, next, { session });
    if (written.matchedCount !== 1) throw new AdminImportError(409, 'ADMIN_IMPORT_REVISION_CONFLICT');
}

/**
 * The saved append's target for the summary, read in the caller's snapshot: the ready Album a saved Album reuse names, with its
 * stored expected tracklist and the Disc and Track Numbers of its declared members of any lifecycle state. Member IDs are read as
 * the Album page and listener reads normalize them (trimmed, lower case, first occurrence kept); a malformed or dangling one fills
 * nothing, and a legacy Album without declared IDs has no members, as the append commit keeps only declared ones. Null without
 * such a reuse, for a missing or not ready Album, one without a tracklist, or one over the member bound publishing enforces.
 */
async function readAppendTarget(decisions: readonly ImportDecisionV2[], session: ClientSession): Promise<ImportAppendTarget | null> {
    const reuse = decisions.find(decision => decision.scope === 'album' && decision.action === 'reuse');
    if (!reuse || !objectId(reuse.candidateId)) return null;
    const db = getDb()!, bound = ADMIN_IMPORT_LIMITS.appendTargetMembers;
    const album = await db.collection('albums').findOne({ _id: new ObjectId(reuse.candidateId), ...readyAlbumLifecycleFilter }, { session, projection: { expectedTracklist: 1, audioTrackIds: 1 }, maxTimeMS: 3_000 });
    if (!album || !hasStoredExpectedTracklist({ expectedTracklist: album.expectedTracklist }) || !Array.isArray(album.audioTrackIds) || album.audioTrackIds.length > bound) return null;
    const ids = [...new Set(album.audioTrackIds.flatMap((value: unknown) => { const id = String(value ?? '').trim().toLowerCase(); return objectId(id) ? [id] : []; }))];
    const members = ids.length ? await db.collection('audioTracks').find({ _id: { $in: ids.map(value => new ObjectId(value)) } }, { session, projection: { discNumber: 1, trackNumber: 1 }, maxTimeMS: 3_000 })
        .limit(bound).toArray() : [];
    return { albumId: album._id.toHexString(), tracklist: album.expectedTracklist, members: members.map(member => ({ discNumber: member.discNumber, trackNumber: member.trackNumber })) };
}

export type ImportLookupResponse = { lookup: ImportLookupView | null; revision: number; valueRevision: number; summary: ImportSummaryView;
    musicBrainzNames: { musicBrainzId: string; names: string[] }[] };
/**
 * The import's lookup view (null before any run), its revision and automatic-write counter, and the Review and publish summary
 * state (importSummaryView) read in the same snapshot: with the provider calls used today, this server's lookup configuration
 * and the identity rows of the saved draft that neither a saved decision nor a preselection answers (the candidates Review reads),
 * and, for a saved append whose publication is not complete, its target's expected tracklist and members (readAppendTarget).
 * `musicBrainzNames` are the names lookup found for each MusicBrainz ID the saved draft carries: a renamed entry keeps its ID
 * only under one of them.
 */
export async function getAdminImportLookup(actor: string, id: string, configuration: () => MetadataLookupConfiguration = metadataLookupConfiguration): Promise<ImportLookupResponse> {
    if (!objectId(id)) throw notFound();
    return withImportAdmin(actor, async session => {
        const doc = await importCollection().findOne({ _id: new ObjectId(id), ...importPurposeFilter }, { session });
        if (!doc) throw notFound();
        const stored = await importLookupRecord(doc._id, session), now = new Date(), identity = await importSavedIdentity(doc, session);
        const preselections = importIdentityPreselections(identity.draft, identity.decisions, identity.candidates);
        const identityAnswers = importIdentityAnswers(identity.draft, identity.decisions, preselections);
        // A complete publication lists no rows (importSummaryView), so its target is not read.
        const appendTarget = doc.media?.publication?.state === 'complete' ? null : await readAppendTarget(identity.decisions, session);
        return { lookup: stored ? importLookupView(stored, doc) : null, revision: doc.revision,
            musicBrainzNames: [...importMusicBrainzNameMap(doc.musicBrainzNames, identity.draft)].map(([musicBrainzId, names]) => ({ musicBrainzId, names })),
            valueRevision: Number.isSafeInteger(doc.valueRevision) && doc.valueRevision! >= 0 ? doc.valueRevision! : 0,
            summary: importSummaryView(doc, stored, { now, dailyAttemptsUsed: await dailyAnalysisAttemptsUsed(now, session), lookupAvailable: configuration().available, identityAnswers,
                appendTarget, preselections }) };
    });
}

/**
 * A submission body `{operationId, expectedRevision, kind, text, artist?}` (an import's or a review's): `kind` album or song, `text`
 * a string within the text bound and `artist`, when present, a string within the same bound, else 400 ADMIN_IMPORT_INVALID_INPUT.
 * The name and Artist name themselves are checked when the run is planned; the intent's fingerprint is the whole body.
 */
export function parseLookupSubmission(raw: unknown) {
    const body = parseAdminProjectMutation(raw, ['kind', 'text', 'artist']);
    if ((body.kind !== 'album' && body.kind !== 'song') || typeof body.text !== 'string' || body.text.length > METADATA_LOOKUP_LIMITS.textLength
        || (hasOwn(body, 'artist') && (typeof body.artist !== 'string' || body.artist.length > METADATA_LOOKUP_LIMITS.textLength))) return invalidImport();
    const submitted: MetadataLookupSubmission = { kind: body.kind as 'album' | 'song', text: body.text,
        ...(hasOwn(body, 'artist') ? { artist: body.artist as string } : {}) };
    return { body, submitted };
}

/**
 * `{operationId, expectedRevision, kind, text, artist?}`: looks up a submitted Album or song name, optionally with an Artist name in
 * place of the shared tag credits, replacing the previous run.
 */
export function submitAdminImportLookup(actor: string, id: string, raw: unknown) {
    const { body, submitted } = parseLookupSubmission(raw);
    return mutateAdminImport(actor, id, body, 'lookup', async (doc, session) => {
        await queueMetadataLookup(doc, { kind: 'submit', actorId: actor, operationId: body.operationId, submitted }, session);
    });
}

/** `{operationId, expectedRevision}`: repeats the last run's queries as a new run. */
export function retryAdminImportLookup(actor: string, id: string, raw: unknown) {
    const body = parseAdminProjectMutation(raw, []);
    return mutateAdminImport(actor, id, body, 'lookup-retry', async (doc, session) => {
        await queueMetadataLookup(doc, { kind: 'retry', actorId: actor, operationId: body.operationId }, session);
    });
}

/** A choice body `{operationId, expectedRevision, run, candidateKey}` (an import's or a review's), else 400 ADMIN_IMPORT_INVALID_INPUT. */
export function parseLookupChoice(raw: unknown) {
    const body = parseAdminProjectMutation(raw, ['run', 'candidateKey']), { run, candidateKey } = boundRunAndCandidate(body);
    return { body, run, candidateKey };
}

/**
 * `{operationId, expectedRevision, run, candidateKey}`: applies a candidate of the current run, or none (`candidateKey: null`); a
 * candidate whose release reports front artwork queues its cover staging under the chooser's fresh grant in this transaction.
 */
export function chooseAdminImportLookup(actor: string, id: string, raw: unknown) {
    const { body, run, candidateKey } = parseLookupChoice(raw);
    return mutateAdminImport(actor, id, body, 'lookup-choose', async (doc, session) => {
        if (!(await metadataLookupAdmitted(doc, session))) throw new AdminImportError(409, 'ADMIN_IMPORT_LOOKUP_REFUSED');
        const stored = await adminImportLookupCollection().findOne({ _id: doc._id }, { session });
        await storeLookupRecord(chooseLookupCandidate(doc, stored, { run, candidateKey, actorId: actor, operationId: body.operationId }, new Date(),
            await readLookupApplicationContext(doc, stored, session)), session);
    });
}

/**
 * An answers body `{operationId, expectedRevision, run, candidateKey, answers}`: 1 to 305 answers (a review's: 1 to 406, also on
 * its review-only paths), each exactly `{path, answer, base}` on a distinct lookup value path (never visibility), `answer` `mine` or
 * `lookup` and `base` bounded JSON; anything else is 400 ADMIN_IMPORT_INVALID_INPUT. The manifest check is the caller's.
 */
export function parseLookupAnswers(raw: unknown, options: { review?: boolean } = {}) {
    const body = parseAdminProjectMutation(raw, ['run', 'candidateKey', 'answers']), { run, candidateKey } = boundRunAndCandidate(body);
    const review = options.review === true, maximum = review ? REVIEW_LOOKUP_LIMITS.answers : maximumAnswers;
    if (!Array.isArray(body.answers) || body.answers.length < 1 || body.answers.length > maximum) return invalidImport();
    const seen = new Set<string>();
    const answers = body.answers.map(item => {
        const answer = record(item); exact(answer, ['path', 'answer', 'base']);
        if (!hasOwn(answer, 'path') || !hasOwn(answer, 'answer') || !hasOwn(answer, 'base') || !isLookupValuePath(answer.path, { review }) || seen.has(answer.path)
            || (answer.answer !== 'mine' && answer.answer !== 'lookup') || !boundedJson(answer.base, 2, DRAFT_V2_LIMITS.bytes)) return invalidImport();
        seen.add(answer.path);
        return { path: answer.path, answer: answer.answer as 'mine' | 'lookup', base: answer.base };
    });
    return { body, run, candidateKey, answers };
}

/**
 * `{operationId, expectedRevision, run, candidateKey, answers}`: answers 1 to 305 conflicts of the applied candidate, each
 * exactly `{path, answer, base}` on a distinct lookup value path (never visibility) of this manifest, `answer` `mine` or `lookup`
 * and `base` the value the answer was made against.
 */
export function resolveAdminImportLookup(actor: string, id: string, raw: unknown) {
    const { body, run, candidateKey, answers } = parseLookupAnswers(raw);
    return mutateAdminImport(actor, id, body, 'lookup-resolve', async (doc, session) => {
        if (!(await metadataLookupAdmitted(doc, session))) throw new AdminImportError(409, 'ADMIN_IMPORT_LOOKUP_REFUSED');
        const parsed = answers.map(answer => ({ ...answer, path: parseDraftPath(answer.path, doc.manifest) }));
        const stored = await adminImportLookupCollection().findOne({ _id: doc._id }, { session });
        await storeLookupRecord(resolveLookupConflicts(doc, stored, { run, candidateKey, answers: parsed }, new Date()), session);
    });
}
